/* @autogenerated */
package net.civeira.phylax.feature.oauth.profile.infrastructure.driven;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import dev.samstevens.totp.code.DefaultCodeGenerator;
import dev.samstevens.totp.code.HashingAlgorithm;
import dev.samstevens.totp.time.SystemTimeProvider;
import net.civeira.phylax.feature.oauth.mfa.infrastructure.OtpMfaService;
import net.civeira.phylax.feature.oauth.profile.domain.MfaSetup;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The second factor managed from the profile, stored with the generated repositories on h2. */
class MfaAdapterUnitTest {
  private OidcRepositories store;
  private MfaAdapter mfa;
  private String tenant;
  private String other;
  private String alice;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    tenant = store.tenant("acme");
    other = store.tenant("globex");
    alice = store.user(tenant, "alice", "alice@acme.test");
    mfa = new MfaAdapter(store.users(), store.userWriter(), new OtpMfaService());
  }

  private static String otp(String seed) throws Exception {
    long window = Math.floorDiv(new SystemTimeProvider().getTime(), 30);
    return new DefaultCodeGenerator(HashingAlgorithm.SHA256).generate(seed, window);
  }

  private static String wrong(String code) {
    return String.format("%06d", (Integer.parseInt(code) + 500_000) % 1_000_000);
  }

  private String column(String name) {
    return store.value("SELECT " + name + " FROM identity_user WHERE uid = '" + alice + "'");
  }

  @Test
  @DisplayName("The setup gives a new seed with its qr image as a data uri")
  void build_setup() {
    MfaSetup setup = mfa.buildSetup(alice, tenant);

    Assertions.assertFalse(setup.seed().isBlank());
    Assertions.assertTrue(setup.getQrImage().orElseThrow().startsWith("data:image/png;base64,"));
    Assertions.assertNotEquals(setup.seed(), mfa.buildSetup(alice, tenant).seed(),
        "Each setup proposes a new seed");
    Assertions.assertFalse(mfa.isEnabled(alice, tenant), "The setup alone does not enable it");
  }

  @Test
  @DisplayName("A valid code enables the second factor with the seed sealed on the user")
  void enable() throws Exception {
    String seed = mfa.buildSetup(alice, tenant).seed();

    mfa.enable(alice, tenant, seed, wrong(otp(seed)));
    Assertions.assertFalse(mfa.isEnabled(alice, tenant), "A wrong code enables nothing");
    Assertions.assertNull(column("second_factor_seed"));

    mfa.enable(alice, tenant, seed, otp(seed));
    Assertions.assertTrue(mfa.isEnabled(alice, tenant));
    String stored = column("second_factor_seed");
    Assertions.assertNotNull(stored);
    Assertions.assertNotEquals(seed, stored, "The seed is not stored in clear");
  }

  @Test
  @DisplayName("Disabling removes the flag and the seed")
  void disable() throws Exception {
    String seed = mfa.buildSetup(alice, tenant).seed();
    mfa.enable(alice, tenant, seed, otp(seed));

    mfa.disable(alice, tenant);

    Assertions.assertFalse(mfa.isEnabled(alice, tenant));
    Assertions.assertEquals("FALSE", column("use_second_factors").toUpperCase());
    Assertions.assertNull(column("second_factor_seed"));
  }

  @Test
  @DisplayName("A user is not managed from another tenant nor when unknown")
  void other_tenant() throws Exception {
    String seed = mfa.buildSetup(alice, tenant).seed();

    Assertions.assertEquals(new MfaSetup("", null), mfa.buildSetup(alice, other));
    Assertions.assertEquals("", mfa.buildSetup("missing", tenant).seed());
    Assertions.assertFalse(mfa.isEnabled("missing", tenant));

    mfa.enable(alice, other, seed, otp(seed));
    Assertions.assertFalse(mfa.isEnabled(alice, tenant));

    mfa.enable(alice, tenant, seed, otp(seed));
    Assertions.assertFalse(mfa.isEnabled(alice, other));
    mfa.disable(alice, other);
    Assertions.assertTrue(mfa.isEnabled(alice, tenant), "Another tenant cannot disable it");
  }
}
